"""Original advanced practice: every source below is a fictional teaching text."""
from . import P

def C(unit, title, text, summary, questions, turns, expressions, writing, speaking, grammar):
    # Dialogue questions require explicit, authored evidence, just like reading questions.
    dialogue, dialogue_questions = turns
    return P(unit,title,text,summary,questions,dialogue,dialogue_questions,expressions,writing,speaking,grammar)

