([("Rédacteur","L’optimisation de la procédure sera poursuivie."),("Lectrice","Qui changera quoi, concrètement ?"),("Rédacteur","L’équipe d’accueil supprimera une étape de saisie."),("Lectrice","Et quand saura-t-on si cela fonctionne ?"),("Rédacteur","Nous comparerons les erreurs après un mois."),("Lectrice","Ces deux précisions rendent l’engagement vérifiable.")],[("Qui modifiera la procédure ?","L’équipe d’accueil.","Un acteur non identifié.","Tous les visiteurs.","L’équipe d’accueil supprimera"),("Quand aura lieu la comparaison ?","Après un mois.","Avant toute modification.","Dans cinq ans.","après un mois")]),
