([("Éditrice","Cette image vient-elle d’une observation ?"),("Auteur","Non, je l’ai imaginée pour une fiction."),("Éditrice","Alors ne la présentons pas comme un témoignage."),("Auteur","Je peux séparer le récit et la notice documentaire."),("Éditrice","Oui, en signalant leur statut."),("Auteur","Les lecteurs sauront ainsi ce qui relève de l’invention.")],[("D’où vient l’image ?","De l’imagination de l’auteur.","D’une enquête vérifiée.","D’une archive citée.","je l’ai imaginée"),("Que doit-on signaler ?","Le statut des deux textes.","Une source inexistante.","Un résultat d’enquête.","en signalant leur statut")]),
