([("Médiatrice","Qu’est-ce qui serait difficile à déplacer ?"),("Théâtre","Les répétitions avec la scène en fin de préparation."),("Atelier","Nous pouvons changer de salle avec deux semaines de préavis."),("Médiatrice","Puis-je noter cet échange comme un accord de principe ?"),("Théâtre","Oui, sous réserve de vérifier les créneaux."),("Atelier","Et de confirmer les compensations par écrit.")],[("Quel préavis demande l’atelier ?","Deux semaines.","Deux heures.","Aucun.","deux semaines de préavis"),("Quel statut a l’accord ?","Un accord de principe sous réserve.","Un engagement définitif sans contrôle.","Un refus total.","accord de principe")]),
